package com.termux.app.workspace;
import org.json.*;
public class ExportProfiles {public static void main(String[] args)throws Exception{JSONObject out=new JSONObject();for(String name:new String[]{"full","confirm","read","project","chat"}){WorkspaceStore.Session s=new WorkspaceStore.Session();s.localModel="qwen35-2b";s.localProtocol="qwen-native";s.localBehaviorMode="brief";s.localAccess=name.equals("chat")?"chat":name.equals("read")?"read":"write";s.localCheckPaths=name.equals("project");s.localConfirmActions=name.equals("confirm")||name.equals("read")||name.equals("project");s.localLocation="ubuntu";s.localEnvironment=LocalAiEnvironment.UBUNTU;s.localProject="/root/projects/jobs-lora-demo";out.put(name,new JSONObject().put("system","You are an action-capable assistant. Reply in the user's language.\n"+LocalAiPrompts.brief()+"\n"+LocalAiPrompts.permissions(s)).put("schemas",LocalAiQwenProtocol.tools(s)));}System.out.println(out);}}
